# Multi-threaded Transport Management System in C#

Below is a complete design for a decoupled, multi-threaded Transport Management System with three isolated modules. The system uses C# with async/await for thread management and implements the requested functionality.

## System Architecture Overview

```
┌───────────────────────────────────────────────────────────────────────────────┐
│                        Transport Management System                          │
├───────────────────┬───────────────────┬───────────────────────────────────────┤
│   Fleet Tracker   │ Route Optimizer   │ Billing & Invoicing                  │
│ (Module 1)        │ (Module 2)        │ (Module 3)                           │
└───────────────────┴───────────────────┴───────────────────────────────────────┘
```

## 1. Fleet Telemetry Tracker (Module 1)

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class FleetTelemetryTracker : IDisposable
{
    private readonly BlockingCollection<VehicleTelemetry> _telemetryQueue;
    private readonly ConcurrentDictionary<string, VehicleState> _vehicleStates;
    private readonly CancellationTokenSource _cts;
    private readonly ITelemetryDataSource _dataSource;
    private readonly ITelemetryProcessor _processor;
    private Task _processingTask;
    private bool _isDisposed;

    public FleetTelemetryTracker(ITelemetryDataSource dataSource, ITelemetryProcessor processor)
    {
        _telemetryQueue = new BlockingCollection<VehicleTelemetry>();
        _vehicleStates = new ConcurrentDictionary<string, VehicleState>();
        _cts = new CancellationTokenSource();
        _dataSource = dataSource ?? throw new ArgumentNullException(nameof(dataSource));
        _processor = processor ?? throw new ArgumentNullException(nameof(processor));
    }

    public void Start()
    {
        if (_processingTask == null || _processingTask.IsCompleted)
        {
            _processingTask = Task.Run(() => ProcessTelemetryAsync(_cts.Token));
        }
    }

    public void Stop()
    {
        _cts.Cancel();
        _telemetryQueue.CompleteAdding();
    }

    private async Task ProcessTelemetryAsync(CancellationToken cancellationToken)
    {
        foreach (var telemetry in _telemetryQueue.GetConsumingEnumerable(cancellationToken))
        {
            try
            {
                // Update vehicle state
                var vehicleState = new VehicleState
                {
                    Id = telemetry.VehicleId,
                    Latitude = telemetry.Latitude,
                    Longitude = telemetry.Longitude,
                    Speed = telemetry.Speed,
                    Timestamp = telemetry.Timestamp,
                    IsMoving = telemetry.Speed > 0.1 // Threshold for movement
                };

                _vehicleStates[vehicleState.Id] = vehicleState;

                // Process anomalies
                var anomalies = _processor.Process(vehicleState);
                if (anomalies.Any())
                {
                    // Publish anomalies to event bus or logging system
                    Console.WriteLine($"Anomalies detected for vehicle {vehicleState.Id}: {string.Join(", ", anomalies)}");
                }

                // Notify route optimizer about new position (Module 2 integration)
                await RouteOptimizer.Instance.UpdateVehiclePositionAsync(vehicleState);
            }
            catch (OperationCanceledException)
            {
                // Expected on cancellation
                break;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing telemetry: {ex.Message}");
            }
        }
    }

    public IEnumerable<VehicleState> GetAllVehicleStates()
    {
        return _vehicleStates.Values;
    }

    public VehicleState GetVehicleState(string vehicleId)
    {
        _vehicleStates.TryGetValue(vehicleId, out var state);
        return state;
    }

    public void Dispose()
    {
        if (_isDisposed) return;

        _isDisposed = true;
        Stop();
        _telemetryQueue.Dispose();
        _cts.Dispose();
    }
}

// Interface for data source (could be GPS device, API, etc.)
