using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class RouteOptimizer : IDisposable
{
    private static readonly Lazy<RouteOptimizer> _instance =
        new Lazy<RouteOptimizer>(() => new RouteOptimizer());

    public static RouteOptimizer Instance => _instance.Value;

    private readonly ConcurrentDictionary<string, VehicleRoute> _vehicleRoutes;
    private readonly BlockingCollection<VehiclePositionUpdate> _positionUpdates;
    private readonly CancellationTokenSource _cts;
    private readonly ITrafficDataService _trafficService;
    private readonly IGraphService _graphService;
    private Task _processingTask;
    private bool _isDisposed;

    private RouteOptimizer()
    {
        _vehicleRoutes = new ConcurrentDictionary<string, VehicleRoute>();
        _positionUpdates = new BlockingCollection<VehiclePositionUpdate>();
        _cts = new CancellationTokenSource();
        _trafficService = new TrafficDataService(); // Could be injected
        _graphService = new GraphService(); // Could be injected
    }

    public void Start()
    {
        if (_processingTask == null || _processingTask.IsCompleted)
        {
            _processingTask = Task.Run(() => ProcessPositionUpdatesAsync(_cts.Token));
        }
    }

    public async Task UpdateVehiclePositionAsync(VehicleState vehicleState)
    {
        if (vehicleState == null || !vehicleState.IsMoving) return;

        await _positionUpdates.AddAsync(new VehiclePositionUpdate
        {
            VehicleId = vehicleState.Id,
            Latitude = vehicleState.Latitude,
            Longitude = vehicleState.Longitude,
            Timestamp = vehicleState.Timestamp
        });
    }

    private async Task ProcessPositionUpdatesAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                var update = await _positionUpdates.TakeAsync(cancellationToken);

                // Get current route for this vehicle
                if (_vehicleRoutes.TryGetValue(update.VehicleId, out var currentRoute))
                {
                    // Check if we need to recalculate route
                    if (ShouldRecalculateRoute(currentRoute, update))
                    {
                        await RecalculateRouteAsync(update.VehicleId, cancellationToken);
                    }
                }
                else
                {
                    // First position for this vehicle - initialize route
                    await InitializeRouteAsync(update.VehicleId, cancellationToken);
                }
            }
            catch (OperationCanceledException)
            {
                // Expected on cancellation
                break;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing position update: {ex.Message}");
            }
        }
    }

    private bool ShouldRecalculateRoute(VehicleRoute route, VehiclePositionUpdate update)
    {
        // Simple heuristic: recalculate if we're far from the current path
        var distanceFromPath = CalculateDistanceFromPath(route.PathPoints, update.Latitude, update.Longitude);
        return distanceFromPath > 500; // 500 meters threshold
    }

    private async Task InitializeRouteAsync(string vehicleId, CancellationToken cancellationToken)
    {
        // Get origin (last known position) and destination (from vehicle config)
        var origin = await GetOriginPositionAsync(vehicleId, cancellationToken);
        var destination = await GetDestinationAsync(vehicleId, cancellationToken);

        if (origin != null && destination != null)
        {
            var route = await CalculateRouteAsync(origin, destination, cancellationToken);
            _vehicleRoutes[vehicleId] = route;

            // Notify billing system about new route (Module 3 integration)
            await BillingSystem.Instance.RouteChangedAsync(vehicleId, route);
        }
    }

    private async Task RecalculateRouteAsync(string vehicleId, CancellationToken cancellationToken)
    {
        var currentRoute = _vehicleRoutes[vehicleId];
        var currentPosition = await GetCurrentPositionAsync(vehicleId, cancellationToken);

        // Get new destination (could be updated)
        var destination = await GetDestinationAsync(vehicleId, cancellationToken);

        if (currentPosition != null && destination != null)
        {
            var newRoute = await CalculateRouteAsync(currentPosition, destination, cancellationToken);
            _vehicleRoutes[vehicleId] = newRoute;

            // Update billing system
            await BillingSystem.Instance.RouteChangedAsync(vehicleId, newRoute);
        }
    }

    private async Task<Route> CalculateRouteAsync(Position origin, Position destination, CancellationToken cancellationToken)
    {
        // Get current traffic data
        var trafficData = await _trafficService.GetTrafficDataAsync(cancellationToken);

        // Get graph with weighted edges based on traffic
        var weightedGraph = await _graphService.GetWeightedGraphAsync(trafficData, cancellationToken);

