## 3. Automated Billing & Invoicing Subsystem (Module 3)

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class BillingSystem : IDisposable
{
    private static readonly Lazy<BillingSystem> _instance =
        new Lazy<BillingSystem>(() => new BillingSystem());

    public static BillingSystem Instance => _instance.Value;

    private readonly BlockingCollection<RouteChangeEvent> _routeChangeEvents;
    private readonly BlockingCollection<VehicleTelemetry> _telemetryEvents;
    private readonly ConcurrentDictionary<string, VehicleBillingInfo> _vehicleBillingInfo;
    private readonly CancellationTokenSource _cts;
    private Task _processingTask;
    private bool _isDisposed;

    private BillingSystem()
    {
        _routeChangeEvents = new BlockingCollection<RouteChangeEvent>();
        _telemetryEvents = new BlockingCollection<VehicleTelemetry>();
        _vehicleBillingInfo = new ConcurrentDictionary<string, VehicleBillingInfo>();
        _cts = new CancellationTokenSource();
    }

    public void Start()
    {
        if (_processingTask == null || _processingTask.IsCompleted)
        {
            _processingTask = Task.Run(() => ProcessBillingEventsAsync(_cts.Token));
        }
    }

    public async Task RouteChangedAsync(string vehicleId, VehicleRoute route)
    {
        if (route == null) return;

        await _routeChangeEvents.AddAsync(new RouteChangeEvent
        {
            VehicleId = vehicleId,
            Route = route,
            Timestamp = DateTime.UtcNow
        });
    }

    public async Task AddTelemetryEventAsync(VehicleTelemetry telemetry)
    {
        if (telemetry == null || !telemetry.IsMoving) return;

        await _telemetryEvents.AddAsync(telemetry);
    }

    private async Task ProcessBillingEventsAsync(CancellationToken cancellationToken)
    {
        // Process route changes first (higher priority)
        var routeChangeTask = Task.Run(async () =>
        {
            foreach (var routeChange in _routeChangeEvents.GetConsumingEnumerable(cancellationToken))
            {
                await ProcessRouteChangeAsync(routeChange, cancellationToken);
            }
        }, cancellationToken);

        // Process telemetry events
        foreach (var telemetry in _telemetryEvents.GetConsumingEnumerable(cancellationToken))
        {
            try
            {
                await ProcessTelemetryAsync(telemetry, cancellationToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing telemetry for billing: {ex.Message}");
            }
        }

        await routeChangeTask;
    }

    private async Task ProcessRouteChangeAsync(RouteChangeEvent routeChange, CancellationToken cancellationToken)
    {
        // Initialize or update billing info for this vehicle
        var billingInfo = new VehicleBillingInfo
        {
            VehicleId = routeChange.VehicleId,
            Route = routeChange.Route,
            Distance = 0,
            TimeSpent = TimeSpan.Zero,
            TollCost = 0,
            FuelCost = 0,
            LastUpdated = DateTime.UtcNow
        };

        _vehicleBillingInfo[routeChange.VehicleId] = billingInfo;

        // Calculate initial tolls based on new route
        await CalculateTollsForRouteAsync(billingInfo, cancellationToken);
    }

    private async Task ProcessTelemetryAsync(VehicleTelemetry telemetry, CancellationToken cancellationToken)
    {
        if (!_vehicleBillingInfo.TryGetValue(telemetry.VehicleId, out var billingInfo))
        {
            // Shouldn't happen if system is working correctly
            return;
        }

        // Update time spent
        var timeDiff = (telemetry.Timestamp - billingInfo.LastUpdated).TotalMinutes;
        billingInfo.TimeSpent = billingInfo.TimeSpent.Add(TimeSpan.FromMinutes(timeDiff));
        billingInfo.LastUpdated = telemetry.Timestamp;

        // Update distance (simplified - in real system would use more precise calculation)
        if (billingInfo.Route.PathPoints.Count > 1)
        {
            var prevPoint = billingInfo.Route.PathPoints[billingInfo.Route.PathPoints.Count - 1];
            var distance = CalculateDistance(prevPoint.Latitude, prevPoint.Longitude,
                                           telemetry.Latitude, telemetry.Longitude);
            billingInfo.Distance += distance;
        }

        // Recalculate tolls periodically
        if (telemetry.Timestamp.Minute % 5 == 0) // Every 5 minutes
        {
            await CalculateTollsForRouteAsync(billingInfo, cancellationToken);
        }
    }

    private async Task CalculateTollsForRouteAsync(VehicleBillingInfo billingInfo, CancellationToken cancellationToken)
    {
        // Get current toll rates
        var tollRates = await GetCurrentTollRatesAsync(cancellationToken);

        // Calculate toll cost based on route and current rates
        var tollCost = CalculateTollCost(billingInfo.Route, tollRates);

        // Calculate fuel cost (simplified)
        var fuelCost = CalculateFuelCost(billingInfo.Distance, billingInfo.TimeSpent);

        // Update billing info
        billingInfo.TollCost = tollCost;
        billingInfo.FuelCost = fuelCost;
        billingInfo.TotalCost = tollCost + fuelCost;

        // Generate invoice if needed (could be done periodically)
        await GenerateInvoiceAsync(billingInfo, cancellationToken);
    }

    private double CalculateTollCost(VehicleRoute route, TollRates tollRates)
    {
        // Simplified toll calculation
        // In real system would use more precise method based on actual toll roads
        return route.Distance * tollRates.KilometerRate + tollRates.FixedFee;
    }

    private double CalculateFuelCost(double distance, TimeSpan timeSpent)
    {
        // Simplified fuel calculation
        const double fuelConsumption = 0.25; // liters per km
        const double fuelPrice = 1.5; // $ per liter
        return distance * fuelConsumption * fuelPrice;
    }

    private async Task GenerateInvoiceAsync(VehicleBillingInfo billingInfo, CancellationToken cancellationToken)
    {
        // Simulate invoice generation
        await Task.Delay(100, cancellationToken);

        Console.WriteLine($"Generating invoice for vehicle {billingInfo.VehicleId}:");
        Console.WriteLine($"  Route: {string.Join(" -> ", billingInfo.Route.PathPoints.Count)} segments");
        Console.WriteLine($"  Distance: {billingInfo.Distance:F2} km");
        Console.WriteLine($"  Time Spent: {billingInfo.TimeSpent.TotalHours:F2} hours");
        Console.WriteLine($"  Toll Cost: ${billingInfo.TollCost:F2}");
        Console.WriteLine($"  Fuel Cost: ${billingInfo.FuelCost:F2}");
        Console.WriteLine($"  Total: ${billingInfo.TotalCost:F2}");
    }

    private async Task<TollRates> GetCurrentTollRatesAsync(CancellationToken cancellationToken)
    {
        // Simulate getting current toll rates
        await Task.Delay(50, cancellationToken);
        return new TollRates
        {
            KilometerRate = 0.15, // $ per km
            FixedFee = 2.00, // $ fixed fee
            PeakHoursRate = 0.25 // $ per km during peak hours
        };
    }

    private double CalculateDistance(double lat1, double lon1, double lat2, double lon2)
    {
        // Simplified distance calculation (Haversine formula would be better)
        var dLat = lat2 - lat1;
        var dLon = lon2 - lon1;
        return Math.Sqrt(dLat * dLat + dLon * dLon) * 111.32; // Approximate km
    }

    public VehicleBillingInfo GetBillingInfo(string vehicleId)
    {
        _vehicleBillingInfo.TryGetValue(vehicleId, out var info);
        return info;
    }

    public void Dispose()
    {
        if (_isDisposed) return;

        _isDisposed = true;
        _cts.Cancel();
        _routeChangeEvents.CompleteAdding();
        _telemetryEvents.CompleteAdding();
        _routeChangeEvents.Dispose();
        _telemetryEvents.Dispose();
        _cts.Dispose();
    }

    // Supporting classes
    public class VehicleBillingInfo
    {
        public string VehicleId { get; set; }
        public VehicleRoute Route { get; set; }
        public double Distance { get; set; } // in km
        public TimeSpan TimeSpent { get; set; }
        public double TollCost { get; set; }
        public double FuelCost { get; set; }
        public double TotalCost { get; set; }
        public DateTime LastUpdated { get; set; }
    }

    public class RouteChangeEvent
    {
        public string VehicleId { get; set; }
        public VehicleRoute Route { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class TollRates
    {
        public double KilometerRate { get; set; }
        public double FixedFee { get; set; }
        public double PeakHoursRate { get; set; }
    }
}
```

## Data Flow Between Module 1 and Module 2

The primary data flow between the Fleet Telemetry Tracker (Module 1) and Route Optimization Engine (Module 2) occurs through the following mechanisms:

1. **Vehicle Position Updates**:
   - When Module 1 receives GPS telemetry for a vehicle, it processes the data and updates the vehicle's state.
   - If the vehicle is moving (speed > threshold), Module 1 calls `UpdateVehiclePositionAsync` on RouteOptimizer.Instance.
   - This method adds the position update to a blocking collection that Module 2's processing task consumes.

2. **Route Recalculation Triggers**:
   - Module 2's processing task checks each incoming position update against the vehicle's current route.
   - If the vehicle is far enough from its current path (using `ShouldRecalculateRoute`), Module 2 triggers a route recalculation.
   - The recalculation uses Dijkstra's algorithm with live traffic data to find the optimal path.

3. **Data Models Shared**:
   - `VehicleState` from Module 1 contains the raw GPS data that becomes the input for Module 2.
   - `VehicleRoute` from Module 2 contains the optimized path that can be used by other modules.

## Integration Points

1. **Module 1 → Module 2**:
   ```csharp
   // In FleetTelemetryTracker.ProcessTelemetryAsync
   await RouteOptimizer.Instance.UpdateVehiclePositionAsync(vehicleState);
   ```

2. **Module 2 → Module 3**:
   ```csharp
   // In RouteOptimizer.InitializeRouteAsync and RecalculateRouteAsync
   await BillingSystem.Instance.RouteChangedAsync(vehicleId, route);
   ```

3. **Module 1 → Module 3** (optional):
   ```csharp
   // Could also send telemetry directly to billing
   await BillingSystem.Instance.AddTelemetryEventAsync(telemetry);
   ```

## Thread Management

The system uses:
- `BlockingCollection<T>` for thread-safe queues between modules
- `CancellationToken` for graceful shutdown
- `Task.Run` for background processing
- Singleton pattern for Module 2 and Module 3 to ensure single instances
- `ConcurrentDictionary` for thread-safe vehicle state storage

## Complete System Initialization

```csharp
class Program
{
    static async Task Main(string[] args)
    {
        // Initialize modules
        var telemetrySource = new MockTelemetryDataSource(); // Implement ITelemetryDataSource
        var telemetryProcessor = new SpeedAnomalyDetector(); // Implement ITelemetryProcessor

        var fleetTracker = new FleetTelemetryTracker(telemetrySource, telemetryProcessor);
        var routeOptimizer = RouteOptimizer.Instance;
        var billingSystem = BillingSystem.Instance;

        // Start all modules
        fleetTracker.Start();
        routeOptimizer.Start();
        billingSystem.Start();

        try
        {
            // Simulate running for some time
            Console.WriteLine("System started. Press any key to stop...");
            Console.ReadKey();

            // Clean shutdown
            fleetTracker.Stop();
            routeOptimizer.Stop();
            billingSystem.Stop();

            // Wait for all tasks to complete
            await Task.WhenAll(
                fleetTracker._processingTask,
                routeOptimizer._processingTask,
                billingSystem._processingTask
            );
        }
        finally
        {
            // Dispose resources
            fleetTracker.Dispose();
            routeOptimizer.Dispose();
            billingSystem.Dispose();
        }
    }
}

